<template><section class="resource-page"><header class="page-header"><div><p class="eyebrow">INTEGRATIONS</p><h1>代码仓库</h1><p class="page-description">管理应用拉取代码及创建 Webhook 所需的访问凭据。</p></div><el-button type="primary" @click="openCreate">添加凭据</el-button></header><el-alert title="仓库凭据属于敏感信息，请只在受信网络中访问管理端。" type="warning" :closable="false" show-icon class="security-alert"/><div class="repo-grid" v-loading="loading"><el-card v-for="item in flatRecords" :key="`${item.provider}-${item.url}-${item.name}`" shadow="never" class="repo-card"><div class="repo-provider" :class="item.provider">{{item.provider.slice(0,2).toUpperCase()}}</div><div class="repo-info"><strong>{{item.name}}</strong><span>{{item.provider}}{{item.url?` · ${item.url}`:''}}</span></div><div class="repo-actions"><el-button link @click="openEdit(item)">更新</el-button><el-button link type="danger" @click="remove(item)">删除</el-button></div></el-card><div v-if="!loading&&!flatRecords.length" class="empty-inline">还没有配置仓库凭据</div></div></section>
<el-dialog v-model="dialog" :title="editing?'更新仓库凭据':'添加仓库凭据'" width="500px"><el-form label-position="top"><el-form-item label="平台"><el-select v-model="form.provider" :disabled="editing"><el-option label="GitHub" value="github"/><el-option label="Gitee" value="gitee"/><el-option label="GitLab" value="gitlab"/></el-select></el-form-item><el-form-item v-if="form.provider==='gitlab'" label="GitLab 地址" required><el-input v-model="form.url" placeholder="https://gitlab.example.com" :disabled="editing"/></el-form-item><el-form-item label="用户名 / 组织名" required><el-input v-model="form.name" :disabled="editing"/></el-form-item><el-form-item label="访问令牌" required><el-input v-model="form.token" type="password" show-password autocomplete="new-password"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{editing?'更新':'添加'}}</el-button></template></el-dialog></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api}from'../api';interface Credential{name:string;token:string;url?:string;provider:'github'|'gitee'|'gitlab'}interface RepoResponse{github:Omit<Credential,'provider'>[];gitee:Omit<Credential,'provider'>[];gitlab:Omit<Credential,'provider'>[]}const data=ref<RepoResponse>({github:[],gitee:[],gitlab:[]}),loading=ref(false),dialog=ref(false),editing=ref(false),saving=ref(false);const form=reactive({provider:'github' as Credential['provider'],name:'',token:'',url:''});const flatRecords=computed<Credential[]>(()=>Object.entries(data.value).flatMap(([provider,list])=>list.map(v=>({...v,provider:provider as Credential['provider']}))));async function load(){loading.value=true;try{data.value=await api.get<RepoResponse>('/repositories')}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}function openCreate(){Object.assign(form,{provider:'github',name:'',token:'',url:''});editing.value=false;dialog.value=true}function openEdit(item:Credential){Object.assign(form,{provider:item.provider,name:item.name,token:'',url:item.url||''});editing.value=true;dialog.value=true}async function save(){if(!form.name||!form.token||(form.provider==='gitlab'&&!form.url))return ElMessage.warning('请填写必填项');saving.value=true;try{const body={name:form.name,token:form.token,url:form.url};if(editing.value)await api.put(`/repositories/${form.provider}`,body);else await api.post(`/repositories/${form.provider}`,body);dialog.value=false;ElMessage.success(editing.value?'凭据已更新':'凭据已添加');load()}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}async function remove(item:Credential){try{await ElMessageBox.confirm(`确定删除 ${item.provider} 凭据 “${item.name}” 吗？`,'删除凭据',{type:'warning'});const q=new URLSearchParams({name:item.name});if(item.url)q.set('url',item.url);await api.delete(`/repositories/${item.provider}?${q}`);ElMessage.success('凭据已删除');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}onMounted(load)</script>
